-- A small sample of the warehouse's source tables (the `lake` schema), used
-- by CI to build and test the dbt project without running the whole
-- pipeline. About sixty synthetic orders over a few days of March 2026,
-- chosen to include cancelled and returned orders, an order without
-- customer, every channel, customers who never ordered and a discontinued
-- product.
--
-- Load it into an empty database:  psql -d warehouse -f ci/sample_lake.sql

CREATE SCHEMA IF NOT EXISTS lake;


CREATE TABLE lake.customers (
    customer_id text,
    first_name text,
    last_name text,
    email text,
    phone text,
    city text,
    postal_code text,
    country text,
    signup_ts timestamp with time zone,
    signup_date date,
    updated_at timestamp with time zone,
    _loaded_at timestamp with time zone
);

CREATE TABLE lake.order_lines (
    order_id text,
    line_number integer,
    source text,
    product_id text,
    quantity integer,
    unit_price numeric(10,2),
    discount_pct integer,
    gross_amount numeric(12,2),
    discount_amount numeric(12,2),
    net_amount numeric(12,2),
    _loaded_at timestamp with time zone
);

CREATE TABLE lake.orders (
    order_id text,
    source text,
    channel text,
    customer_id text,
    order_ts timestamp with time zone,
    order_date date,
    status text,
    status_ts timestamp with time zone,
    is_cancelled boolean,
    is_returned boolean,
    paid_at timestamp with time zone,
    shipped_at timestamp with time zone,
    delivered_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    returned_at timestamp with time zone,
    payment_method text,
    shipping_city text,
    shipping_postal_code text,
    lines_count integer,
    units integer,
    gross_amount numeric(12,2),
    discount_amount numeric(12,2),
    net_amount numeric(12,2),
    shipping_fee numeric(10,2),
    total_amount numeric(12,2),
    source_total_amount numeric(12,2),
    _loaded_at timestamp with time zone
);

CREATE TABLE lake.products (
    product_id text,
    name text,
    category text,
    brand text,
    unit_price numeric(10,2),
    currency text,
    is_active boolean,
    created_at timestamp with time zone,
    updated_at timestamp with time zone,
    _loaded_at timestamp with time zone
);






-- History of data-quality checks: one run of the quality job, and two
-- snapshots of the reject counts.


CREATE TABLE lake.quality_check_results (
    run_id text,
    checked_at timestamp with time zone,
    layer text,
    table_name text,
    check_name text,
    dimension text,
    severity text,
    description text,
    expectation text,
    column_name text,
    success boolean,
    status text,
    element_count bigint,
    unexpected_count bigint,
    unexpected_percent double precision,
    observed_value text,
    sample text,
    _loaded_at timestamp with time zone
);

CREATE TABLE lake.quality_reject_history (
    run_id text,
    checked_at timestamp with time zone,
    source text,
    reason text,
    rejected bigint,
    _loaded_at timestamp with time zone
);



